package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;
/** One reversible local settings transaction; credentials and content are never journaled. */
final class SettingsJournal {
 static boolean allowed(String file,String key){return file.equals("device_tuning")&&key.matches("enabled|normal|navigation|meeting|adaptive")||file.equals("navigation_display")&&key.matches("full_body_mode|lower_half|upper_half");}
 static synchronized void change(Context c,String file,JSONObject edits)throws Exception{recover(c);if(edits.length()<1||edits.length()>8)throw new IllegalArgumentException("設定件数を確認してください");SharedPreferences prefs=c.getSharedPreferences(file,0);JSONObject before=new JSONObject();SharedPreferences.Editor e=prefs.edit();for(java.util.Iterator<String> it=edits.keys();it.hasNext();){String key=it.next();if(!allowed(file,key))throw new IllegalArgumentException("戻せる設定の対象外です");Object value=edits.get(key);if(!(value instanceof Boolean)&&!(value instanceof Integer))throw new IllegalArgumentException("設定の型が不正です");Object previous=prefs.getAll().get(key);before.put(key,previous==null?JSONObject.NULL:previous);if(value instanceof Boolean)e.putBoolean(key,(Boolean)value);else{int n=(Integer)value;if(n<0||n>100)throw new IllegalArgumentException("設定値を確認してください");e.putInt(key,n);}}if(matches(c,file,edits))return;String journal=new JSONObject().put("file",file).put("before",before).put("after",edits).toString();SharedPreferences history=c.getSharedPreferences("settings_undo",0);if(!history.edit().putString("pending",journal).commit())throw new java.io.IOException("変更前の設定を保存できません");if(!e.commit()){history.edit().remove("pending").commit();throw new java.io.IOException("設定を保存できません");}if(!history.edit().putString("latest",journal).remove("pending").commit())throw new java.io.IOException("設定は保存しましたが取り消し記録を確定できません");}
 static synchronized String undo(Context c)throws Exception{recover(c);SharedPreferences history=c.getSharedPreferences("settings_undo",0);if(!history.getString("pending","").isEmpty())return "前回の設定保存が未確定です。上書きせず停止しました";String raw=history.getString("latest","");if(raw.isEmpty())return "戻せる設定の記録はありません";JSONObject j=new JSONObject(raw),before=j.getJSONObject("before"),after=j.getJSONObject("after");String file=j.getString("file");SharedPreferences prefs=c.getSharedPreferences(file,0);for(java.util.Iterator<String> it=after.keys();it.hasNext();){String key=it.next();if(!allowed(file,key)||!java.util.Objects.equals(prefs.getAll().get(key),after.get(key)))return "設定がさらに変更されたため、上書きせず停止しました";}if(before.length()!=after.length())throw new java.io.IOException("取り消し記録が不正です");SharedPreferences.Editor e=prefs.edit();for(java.util.Iterator<String> it=before.keys();it.hasNext();){String key=it.next();if(!allowed(file,key)||!after.has(key))throw new java.io.IOException("取り消し対象が不正です");Object value=before.get(key);if(value==JSONObject.NULL)e.remove(key);else if(value instanceof Boolean)e.putBoolean(key,(Boolean)value);else if(value instanceof Integer)e.putInt(key,(Integer)value);else throw new java.io.IOException("取り消し記録を確認できません");}if(!e.commit())throw new java.io.IOException("設定を戻せませんでした");history.edit().remove("latest").commit();return "直前の対応設定を戻しました。APIキー・会話・記録には変更ありません";}
 static boolean matches(Context c,String file,JSONObject values)throws Exception{SharedPreferences prefs=c.getSharedPreferences(file,0);for(java.util.Iterator<String> it=values.keys();it.hasNext();){String key=it.next();if(!allowed(file,key))return false;Object expected=values.get(key);if(expected==JSONObject.NULL)expected=null;if(!java.util.Objects.equals(expected,prefs.getAll().get(key)))return false;}return true;}
 static void recover(Context c)throws Exception{SharedPreferences history=c.getSharedPreferences("settings_undo",0);String raw=history.getString("pending","");if(raw.isEmpty())return;JSONObject j=new JSONObject(raw);String file=j.getString("file");if(matches(c,file,j.getJSONObject("after"))){if(!history.edit().putString("latest",raw).remove("pending").commit())throw new java.io.IOException("取り消し記録を確定できません");}else if(matches(c,file,j.getJSONObject("before"))){if(!history.edit().remove("pending").commit())throw new java.io.IOException("保存状態を確認できません");}else throw new java.io.IOException("未確定の設定と現在の値が異なります。上書きせず停止しました");}
 private SettingsJournal(){}
}
